export const CDN = "https://res.cloudinary.com/idmvpeay/image/upload";

export type HospitalImage = { file: string; alt: string };

export function img(file: string, width = 900): string {
  return `${CDN}/f_auto,q_auto,c_limit,w_${width}/${file}`;
}

export function coverImg(file: string, width = 1920, height = 1080): string {
  return `${CDN}/f_auto,q_auto,c_fill,g_auto,w_${width},h_${height}/${file}`;
}

export function containImg(file: string, width = 1200, height = 1600): string {
  return `${CDN}/f_auto,q_auto,c_limit,w_${width},h_${height}/${file}`;
}


